cache={}; pins={}
def git(*args): return subprocess.check_output([G,*args])
assert git('show','-s','--format=%T',C).decode().strip()==T
def blob(p,c=C):
 k=(c,p)
 if k not in cache:
  raw=git('show',c+':'+p); tree=git('ls-tree',c,'--',p).decode().strip().split(); assert tree[1]=='blob'
  cache[k]=raw; pins[c+':'+p]={'commit':c,'path':p,'git_blob':tree[2],'git_mode':tree[0],'sha256':sha(raw),'bytes':len(raw)}
 return cache[k]
def decls(p,c=C):
 lines=blob(p,c).splitlines(keepends=True); out=[]
 for i,l in enumerate(lines):
  if not l.startswith(b'func '): continue
  m=re.match(rb'func (?:\([^\n]*?\) )?([A-Za-z_][A-Za-z_0-9]*)(?:\[[^\n]*?\])?\(',l)
  if not m: continue
  end=i if l.rstrip().endswith(b'}') else next(j for j in range(i+1,len(lines)) if lines[j].rstrip(b'\r\n')==b'}')
  raw=b''.join(lines[i:end+1]).removesuffix(b'\n')
  out.append({'path':p,'function':m[1].decode(),'start_line':i+1,'end_line':end+1,'sha256':sha(raw),'git_blob':pins[c+':'+p]['git_blob'],'file_pin':c+':'+p})
 return out
def raw_decl(p,n,c=C):
 d=next(x for x in decls(p,c) if x['function']==n); return d,b'\n'.join(blob(p,c).splitlines()[d['start_line']-1:d['end_line']])
